<?php
define('KARVIA_APP', true);
$peran_halaman = 'siswa';
$halaman_aktif = 'bandingkan';
$judul_halaman = 'Bandingkan Pilihan';
require_once __DIR__ . '/../includes/header.php';
$pdo = db(); $siswa_id = (int) auth_pengguna()['id'];
$stmt = $pdo->prepare('SELECT opsi_a,catatan_a,opsi_b,catatan_b,kriteria FROM pilihan_banding WHERE siswa_id=:id'); $stmt->execute(['id'=>$siswa_id]);
$data = $stmt->fetch() ?: ['opsi_a'=>'','catatan_a'=>'','opsi_b'=>'','catatan_b'=>'','kriteria'=>'[]'];
$profesi_id = filter_input(INPUT_GET,'profesi',FILTER_VALIDATE_INT) ?: 0;
if ($profesi_id && !$data['opsi_a']) { $q=$pdo->prepare("SELECT nama FROM profesi WHERE id=:id AND status='aktif'");$q->execute(['id'=>$profesi_id]);$data['opsi_a']=(string)($q->fetchColumn() ?: ''); }
$criteria=['Kesesuaian minat','Peluang belajar','Lama pendidikan','Dampak bagi orang lain'];$chosen=json_decode($data['kriteria'] ?: '[]',true) ?: [];$errors=[];
if ($_SERVER['REQUEST_METHOD']==='POST') { csrf_wajib(); $data=['opsi_a'=>trim((string)($_POST['opsi_a']??'')),'catatan_a'=>trim((string)($_POST['catatan_a']??'')),'opsi_b'=>trim((string)($_POST['opsi_b']??'')),'catatan_b'=>trim((string)($_POST['catatan_b']??''))];$selected=$_POST['kriteria']??[];if(!is_array($selected))$selected=[];$chosen=array_values(array_intersect($criteria,array_map('strval',$selected)));foreach(['opsi_a'=>150,'catatan_a'=>5000,'opsi_b'=>150,'catatan_b'=>5000] as $key=>$max){if(mb_strlen($data[$key])>$max)$errors[]='Ada isian yang terlalu panjang.';}if($data['opsi_a']===''||$data['opsi_b']==='')$errors[]='Kedua pilihan wajib diisi.';if($data['opsi_a']===$data['opsi_b'])$errors[]='Pilih dua pilihan yang berbeda.';if(!$errors){$q=$pdo->prepare('INSERT INTO pilihan_banding (siswa_id,opsi_a,catatan_a,opsi_b,catatan_b,kriteria,dibuat_pada) VALUES (:id,:a,:ca,:b,:cb,:k,NOW()) ON DUPLICATE KEY UPDATE opsi_a=VALUES(opsi_a),catatan_a=VALUES(catatan_a),opsi_b=VALUES(opsi_b),catatan_b=VALUES(catatan_b),kriteria=VALUES(kriteria),diperbarui_pada=NOW()');$q->execute(['id'=>$siswa_id,'a'=>$data['opsi_a'],'ca'=>$data['catatan_a']?:null,'b'=>$data['opsi_b'],'cb'=>$data['catatan_b']?:null,'k'=>json_encode($chosen,JSON_UNESCAPED_UNICODE)]);flash_set('sukses','Perbandingan berhasil disimpan.');redirect('siswa/bandingkan.php');}}
?>
<div class="mb-6"><h1 class="text-2xl font-extrabold">Bandingkan Pilihan</h1><p class="mt-1 text-sm text-slate-600">Tidak ada pilihan yang otomatis ditetapkan. Gunakan kriteria yang penting bagimu.</p></div>
<?php if($errors): ?><div role="alert" class="mb-4 rounded-xl bg-rose-50 p-4 text-sm text-rose-800"><?php foreach($errors as $error): ?><p><?=e($error)?></p><?php endforeach;?></div><?php endif;?>
<form method="post" class="max-w-4xl space-y-5 rounded-2xl border bg-white p-6"><?=csrf_field()?><div class="grid gap-5 md:grid-cols-2"><?php foreach(['a'=>'Pilihan A','b'=>'Pilihan B'] as $s=>$label): ?><fieldset class="space-y-3"><legend class="font-bold"><?=e($label)?></legend><label class="block text-sm">Nama pilihan<input required maxlength="150" name="opsi_<?= $s ?>" value="<?=e($data['opsi_'.$s])?>" class="mt-1 w-full rounded-lg border p-2"></label><label class="block text-sm">Catatan<textarea maxlength="5000" name="catatan_<?= $s ?>" rows="4" class="mt-1 w-full rounded-lg border p-2"><?=e($data['catatan_'.$s])?></textarea></label></fieldset><?php endforeach;?></div><fieldset><legend class="mb-2 font-bold">Kriteria pertimbangan</legend><div class="grid gap-2 sm:grid-cols-2"><?php foreach($criteria as $c): ?><label class="flex gap-2 rounded-lg border p-3 text-sm"><input type="checkbox" name="kriteria[]" value="<?=e($c)?>" <?=in_array($c,$chosen,true)?'checked':''?>><?=e($c)?></label><?php endforeach;?></div></fieldset><button class="rounded-xl bg-emerald-700 px-5 py-2.5 font-bold text-white">Simpan Perbandingan</button></form>
<?php require __DIR__ . '/../includes/footer.php'; ?>
